// iNavarro client portal: verified static release and reproducible source snapshot.
// Build: npm ci && npm run check && npm run build in the source/ snapshot.
// Only the publishable Supabase key is included; privileged keys are never bundled.
import fs from 'node:fs';
import path from 'node:path';
import {gunzipSync} from 'node:zlib';
const release=JSON.parse(gunzipSync(Buffer.from('','base64')).toString('utf8'));
for(const [file,encoded] of Object.entries(release)){
 if(!file.startsWith('public/'))continue;
 const relative=file.slice(7);if(relative.includes('..'))throw new Error('Invalid portal release path');
 const target=path.join('dist/clientes/acceso',relative);fs.mkdirSync(path.dirname(target),{recursive:true});fs.writeFileSync(target,Buffer.from(encoded,'base64'));
}
const home='dist/clientes/index.html';let landing=fs.readFileSync(home,'utf8');
landing=landing.replace(/<main id="contenido">[\s\S]*?<\/main>/,'<main id="contenido"><article class="post"><div class="eyebrow">iNAVARRO ABOGADOS · ÁREA PRIVADA</div><h1>Tu acceso al despacho.</h1><p class="lead">Crea tu cuenta con tu correo y una contraseña. Confirma el correo para activar tu acceso.</p><p><a class="contact" href="/clientes/acceso/?mode=signup">Crear mi cuenta ↗</a></p><p><a href="/clientes/acceso/">Ya tengo cuenta · Iniciar sesión ↗</a></p><p>El despacho asigna individualmente los expedientes que puedes consultar. La creación de una cuenta no supone la aceptación de un encargo profesional. La recepción de documentos se habilita por separado para cada asunto.</p><p><a href="/privacidad-clientes/">Información de protección de datos ↗</a></p><p>Si tienes una urgencia o un plazo próximo, llama al <a href="tel:+34634330504">634 330 504</a>.</p></article></main>');
fs.writeFileSync(home,landing);
const privacy='dist/privacidad-clientes/index.html';let p=fs.readFileSync(privacy,'utf8');
p=p.replace('<strong>Área en preparación:</strong> todavía no admite creación de cuentas ni recepción de documentación de clientes.','<strong>Registro de cuentas habilitado:</strong> puedes crear tu cuenta y confirmar tu correo. El acceso a expedientes requiere asignación individual del despacho. La recepción de documentación se habilita por separado.');
p=p.replace('PROTECCIÓN DE DATOS · 12 OCTUBRE 2026','PROTECCIÓN DE DATOS · 21 OCTUBRE 2026');
p=p.replace('El acceso se habilita individualmente por el despacho; no permite consultar expedientes de otros clientes.','Puedes crear una cuenta con tu correo y contraseña; el despacho habilita individualmente el acceso a cada expediente. No permite consultar los asuntos de otros clientes.');
p=p.replace('Para identificar a los clientes autorizados, gestionar su acceso,','Para crear y administrar cuentas, verificar el correo, autenticar y recuperar el acceso, proteger las sesiones e identificar a los clientes autorizados,');
p=p.replace('Correo e identificador de autenticación, referencias y estado de los asuntos,','Correo, identificador de autenticación, estado de confirmación, sesiones y factores de autenticación gestionados por Supabase, referencias y estado de los asuntos,');
p=p.replace('El área de clientes prevista utiliza Supabase para la autenticación, la base de datos y los archivos privados; la web pública se aloja en Render. El acceso opcional con Google implica también la intervención de ese proveedor de identidad. La recepción de documentación permanecerá cerrada hasta completar la habilitación del servicio.','El área de clientes utiliza Supabase para autenticación, base de datos y archivos privados; la web se aloja en Render. Los mensajes de confirmación y recuperación se envían mediante Gmail de Google, configurado por el despacho. El registro funciona con correo y contraseña. El despacho no recibe ni puede consultar tu contraseña en texto legible. La recepción de documentación permanece cerrada hasta su habilitación específica.');
p=p.replace('Antes de habilitar el registro y la documentación real,','Antes de habilitar la documentación real,');
fs.writeFileSync(privacy,p);
console.log('Client registration published: email/password with required email verification.');
